"region_id","metric_code","plan_version"],"event_time":"target_month / approved_at","visible_time":"available_at","fields":{"metric_code":"目标口径","plan_version":"计划版","target_cent":"目标分","approved_at":"批准时刻"},"joins":[]},"position":"entities.json#target_monthly"},{"ref":"platform/sales.order_count","scope":"platform","kind":"metric","code":"sales.order_count","domain":"sales","name":"下单订单数","summary":"按原销售归属统计期间内创建的订单。","responsible":"平台经营指标负责人","grain":"每租户每张订单一次","unit":"order","definition":{"formula":"COUNT(期间内创建的订单)","components":"唯一订单","aggregation":"订单头计数；跨商品集合重新去重。","event_time":"下单时刻","timezone":"Asia/Shanghai","calendar":"公历自然日，ISO 周","window":"[start,end)","known_at":"available_at <= as_of","exceptions":"保留取消单；一单包含多个指定商品时只计一次；空销售网点保留未归属。","dimensions":["day","channel","region","site"],"filters":["channel","region","site","sku","spu","category"],"display":"整数单","additivity":"additive_across_disjoint_order_sets"},"position":"metrics.json#sales.order_count"},{"ref":"101.sales/sales.paid_gmv","scope":"101.sales","kind":"metric","code":"sales.paid_gmv","domain":"sales","name":"支付 GMV","summary":"在支付成功归属期内合计实收款项。","responsible":"销售运营负责人","grain":"一笔成功支付","unit":"CNY_fen","definition":{"formula":"SUM(成功支付金额分)","components":"成功支付额","aggregation":"按支付事件加总。","event_time":"成功行 attempted_at","timezone":"Asia/Shanghai","calendar":"公历自然日，ISO 周","window":"[start,end)","known_at":"available_at <= as_of","exceptions":"失败尝试除外；教学时间代理需在切换生产清算源时复审；商品拆分需获批分摊规则。","dimensions":["day","channel","region","site"],"filters":["channel","region","site"],"display":"加总分后除以 100，以人民币元保留两位","additivity":"additive_at_declared_grain"},"position":"metrics.json#sales.paid_gmv"},{"ref":"102.sales/sales.paid_gmv","scope":"102.sales","kind":"metric","code":"sales.paid_gmv","domain":"sales","name":"支付 GMV","summary":"在支付成功归属期内合计实收款项。","responsible":"销售运营负责人","grain":"一笔成功支付","unit":"CNY_fen","definition":{"formula":"SUM(成功支付金额分)","components":"成功支付额","aggregation":"按支付事件加总。","event_time":"成功行 attempted_at","timezone":"Asia/Shanghai","calendar":"公历自然日，ISO 周","window":"[start,end)","known_at":"available_at <= as_of","exceptions":"失败尝试除外；教学时间代理需在切换生产清算源时复审；商品拆分需获批分摊规则。","dimensions":["day","channel","region","site"],"filters":["channel","region","site"],"display":"加总分后除以 100，以人民币元保留两位","additivity":"additive_at_declared_grain"},"position":"metrics.json#sales.paid_gmv"},{"ref":"101/sales.net_gmv","scope":"101","kind":"metric","code":"sales.net_gmv","domain":"sales","name":"现金流净 GMV","summary":"同期成功支付减同期成功退款，退款回到原单销售维度。","responsible":"租户经营负责人","grain":"一笔有符号的成功收退款事件","unit":"CNY_fen","definition":{"formula":"SUM(成功支付金额分) − SUM(成功退款金额分)","components":"成功支付额；成功退款额","aggregation":"正负两支分别取时，UNION ALL 后按授权范围合计。","event_time":"支付或退款各自的 attempted_at","timezone":"Asia/Shanghai","calendar":"公历自然日，ISO 周","window":"[start,end)","known_at":"available_at <= as_of","exceptions":"退款源金额为正；保留上期订单的本期退款；净额可为负。","dimensions":["day","channel","region","site"],"filters":["channel","region","site"],"display":"加总分后除以 100，以人民币元保留两位","additivity":"additive_at_declared_grain"},"position":"metrics.json#sales.net_gmv"},{"ref":"102/sales.net_gmv","scope":"102","kind":"metric","code":"sales.net_gmv","domain":"sales","name":"现金流净 GMV","summary":"同期成功支付减同期成功退款，退款回到原单销售维度。","responsible":"租户经营负责人","grain":"一笔有符号的成功收退款事件","unit":"CNY_fen","definition":{"formula":"SUM(成功支付金额分) − SUM(成功退款金额分)","components":"成功支付额；成功退款额","aggregation":"正负两支分别取时，UNION ALL 后按授权范围合计。","event_time":"支付或退款各自的 attempted_at","timezone":"Asia/Shanghai","calendar":"公历自然日，ISO 周","window":"[start,end)","known_at":"available_at <= as_of","exceptions":"退款源金额为正；保留上期订单的本期退款；净额可为负。","dimensions":["day","channel","region","site"],"filters":["channel","region","site"],"display":"加总分后除以 100，以人民币元保留两位","additivity":"additive_at_declared_grain"},"position":"metrics.json#sales.net_gmv"},{"ref":"101.finance/finance.recognized_revenue","scope":"101.finance","kind":"metric","code":"finance.recognized_revenue","domain":"finance","name":"确认收入",