.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"b366da595710594f13250e6daefcee6d66f4a20c6486d12ceaecefffab043d19","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day","channel","region","site"]},"filters":{"type":"object","additionalProperties":false,"properties":{"channel":{"type":"integer","minimum":1,"maximum":9007199254740991},"region":{"type":"integer","minimum":1,"maximum":9007199254740991},"site":{"type":"integer","minimum":1,"maximum":9007199254740991},"sku":{"type":"integer","minimum":1,"maximum":9007199254740991},"spu":{"type":"integer","minimum":1,"maximum":9007199254740991},"category":{"type":"integer","minimum":1,"maximum":9007199254740991}}}}},"result_schema":{"type":"object","additionalProperties":false,"required":["group_key","value","status","detail","period_start","period_end","as_of","data_release","business_timezone","unit"],"properties":{"group_key":{"type":["string","null"]},"value":{"type":["string","null"],"pattern":"^-?[0-9]+(\\.[0-9]+)?$"},"status":{"enum":["OK","INVALID_WINDOW","UNSUPPORTED_DIMENSION","UNSUPPORTED_FILTER","SCOPE_DENIED","RELEASE_UNAVAILABLE","OUTSIDE_COVERAGE","SOURCE_DELAYED","COVERAGE_UNKNOWN","NO_FACTS"]},"detail":{"type":"object"},"period_start":{"type":"string","format":"date"},"period_end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"data_release":{"type":"string"},"business_timezone":{"const":"Asia/Shanghai"},"unit":{"const":"order"}},"if":{"properties":{"status":{"const":"OK"}}},"then":{"properties":{"value":{"type":"string"}}},"else":{"properties":{"value":{"type":"null"}}}},"target_ref":"compass-retail/semantic-content/1/sales.order_count","access":{"scope":"regional","source_release":"diagnost