             WHEN i.dim <> ''total'' AND NOT (spec->''dimensions'' ? i.dim) THEN ''UNSUPPORTED_DIMENSION''\n                WHEN EXISTS (SELECT FROM jsonb_object_keys(i.filters) f WHERE NOT (spec->''filters'' ? f))\n                     THEN ''UNSUPPORTED_FILTER''\n                WHEN i.all_regions IS NULL OR (NOT i.all_regions AND\n                     (coalesce(jsonb_array_length(i.region_ids),0) = 0 OR spec->>''access'' = ''all_regions''\n                      OR (i.filters ? ''region'' AND NOT (i.region_ids @> jsonb_build_array(i.filters->''region'')))))\n                     THEN ''SCOPE_DENIED''\n                WHEN t.release_id IS NULL OR i.release_id IS DISTINCT FROM t.release_id\n                     OR t.release_id <> spec->>''release'' THEN ''RELEASE_UNAVAILABLE''\n                WHEN (CASE WHEN spec ? ''first_snapshot'' THEN i.d1-1 ELSE i.d0 END) < (spec->>''start'')::date OR i.d1 > (spec->>''end'')::date THEN ''OUTSIDE_COVERAGE''\n           END AS invalid\n    FROM input i CROSS JOIN contract LEFT JOIN tenant t ON t.tenant_id = i.tenant_id\n), p AS (SELECT * FROM checked WHERE invalid IS NULL)\n\n, paid AS (\n    SELECT f.tenant_id, f.order_id, f.region_id, f.attempted_at, f.amount_cent\n    FROM p JOIN payment f ON f.tenant_id=p.tenant_id\n    WHERE f.status=''SUCCEEDED'' AND f.attempted_at >= p.start_at AND f.attempted_at < p.end_at AND f.available_at <= p.k\n)\n\n, cash AS (SELECT * FROM paid)\n\n, facts AS (\n    SELECT f.attempted_at AS event_at, o.channel_id, o.region_id, o.selling_site_id AS site_id,\n           NULL::bigint AS sku_id, NULL::bigint AS spu_id, NULL::bigint AS category_id, f.amount_cent AS amount, NULL::integer AS report_version\n    FROM cash f JOIN order_header o USING (tenant_id, order_id, region_id)\n    CROSS JOIN p WHERE o.available_at <= p.k\n)\n\n, watermarks AS (\n    SELECT source, last_seen.observed_at, last_seen.complete_through, last_seen.status\n    FROM p CROSS JOIN contract CROSS JOIN jsonb_array_elements_text(spec->''watermarks'') source\n    LEFT JOIN LATERAL (\n        SELECT w.observed_at, w.complete_through, w.status FROM source_watermark w\n        WHERE w.tenant_id=p.tenant_id AND w.source_system=source AND w.observed_at <= p.k\n        ORDER BY w.observed_at DESC LIMIT 1\n    ) last_seen ON true\n), coverage AS (\n    SELECT CASE WHEN count(*) FILTER (WHERE w.observed_at IS NULL)>0 THEN ''COVERAGE_UNKNOWN''\n                WHEN bool_or(w.status=''FAILED'' OR w.complete_through < p.end_at) THEN ''SOURCE_DELAYED''\n           END AS gap,\n           jsonb_build_object(''watermarks'',jsonb_object_agg(source,to_jsonb(w)-''source'')) AS detail\n    FROM watermarks w CROSS JOIN p\n)\n\n, grouped AS (\n    SELECT CASE p.dim WHEN ''day'' THEN (event_at AT TIME ZONE ''Asia/Shanghai'')::date::text\n               WHEN ''channel'' THEN channel_id::text WHEN ''region'' THEN region_id::text\n               WHEN ''site'' THEN site_id::text WHEN ''sku'' THEN sku_id::text WHEN ''spu'' THEN spu_id::text\n               WHEN ''category'' THEN category_id::text ELSE ''total'' END AS group_key,\n           sum(amount)::numeric AS value,\n           array_agg(DISTINCT report_version ORDER BY report_version) FILTER (WHERE report_version IS NOT NULL) AS versions\n    FROM facts CROSS JOIN p\n    WHERE (p.all_regions OR p.region_ids @> jsonb_build_array(region_id))\n      AND (NOT p.filters ? ''channel'' OR channel_id=(p.filters->>''channel'')::bigint)\n      AND (NOT p.filters ? ''region'' OR region_id=(p.filters->>''region'')::bigint)\n      AND (NOT p.filters ? ''site'' OR site_id=(p.filters->>''site'')::bigint)\n      -- Orders applied the three product filters in one correlated EXISTS before counting.\n      AND (sku_id IS NULL OR NOT p.filters ? ''sku'' OR sku_id=(p.filters->>''sku'')::bigint)\n      AND (spu_id IS NULL OR NOT p.filters ? ''spu'' OR spu_id=(p.filters->>''spu'')::bigint)\n      AND (category_id IS NULL OR NOT p.filters ? ''category'' OR category_id=(p.filters->>''category'')::bigint)\n    GROUP BY 1\n), results AS (\n    SELECT g.group_key, CASE WHEN c.gap IS NULL THEN g.value END AS value,\n           coalesce(c.gap,''OK'') AS status, c.detail ||\n           CASE WHEN g.versions IS NULL THEN ''{}''::jsonb ELSE jsonb_build_object(''report_versions'',g.versions) END AS detail\n    FROM grouped g CROSS JOIN coverage c\n    UNION ALL\n    SELECT CASE WHEN p.dim=''total'' THEN ''total'' END,\n           CASE WHEN c.gap IS NULL AND p.dim=''total'' THEN 0::numeric END,\n           coalesce(c.gap, CASE WHEN p.dim=''total'' THEN ''OK'' ELSE ''NO_FACTS'' END), c.detail\n    FROM p CROSS JOIN coverage c WHERE NOT EXISTS (SELECT FROM grouped)\n)\n\nSELECT group_key, value, status, detail, c.d0 AS period_start, c.d1 AS period_end,\n       c.k AS as_of, c.release_id AS data_release, ''Asia/Shanghai''::text AS business_timezone,\n       spec->>''unit'' AS unit\nFROM checked c CROSS JOIN contract CROSS JOIN LATERAL (\n    SELECT r.* FROM results r WHERE c.invalid IS NULL\n    UNION ALL\n    SELECT NULL::text, NULL::numeric, c.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"1192cb0d05acce3f18c92c724d05f82b47b2d008944fdce6465d866c041a664b","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day","channel","region","site"]},"filters":{"type":"object","additionalProperties":false,"properties":{"channel":{"type":"integer","minimum":1,"maximum":9007199254740991},"region":{"type":"integer","minimum":1,"maximum":9007199254740991},"site":{"type":"integer","minimum":1,"maximum":9007199254740991}}}}},"result_schema":{"type":"object","additionalProperties":false,"required":["group_key","value","status","detail","period_start","period_end","as_of","data_release","business_time