.d1 > (spec->>''end'')::date THEN ''OUTSIDE_COVERAGE''\n           END AS invalid\n    FROM input i CROSS JOIN contract LEFT JOIN tenant t ON t.tenant_id = i.tenant_id\n), p AS (SELECT * FROM checked WHERE invalid IS NULL)\n\n, paid AS (\n    SELECT f.tenant_id, f.order_id, f.region_id, f.attempted_at, f.amount_cent\n    FROM p JOIN payment f ON f.tenant_id=p.tenant_id\n    WHERE f.status=''SUCCEEDED'' AND f.attempted_at >= p.start_at AND f.attempted_at < p.end_at AND f.available_at <= p.k\n)\n\n, cash AS (\n    SELECT * FROM paid\n    UNION ALL\n    SELECT r.tenant_id, r.order_id, r.region_id, r.attempted_at, -r.amount_cent\n    FROM p JOIN refund r ON r.tenant_id=p.tenant_id\n    JOIN payment original ON (original.tenant_id,original.payment_id,original.order_id,original.region_id)\n                           =(r.tenant_id,r.payment_id,r.order_id,r.region_id)\n    WHERE r.status=''SUCCEEDED'' AND original.status=''SUCCEEDED'' AND original.available_at <= p.k\n      AND r.attempted_at >= p.start_at AND r.attempted_at < p.end_at AND r.available_at <= p.k\n)\n\n, facts AS (\n    SELECT f.attempted_at AS event_at, o.channel_id, o.region_id, o.selling_site_id AS site_id,\n           NULL::bigint AS sku_id, NULL::bigint AS spu_id, NULL::bigint AS category_id, f.amount_cent AS amount, NULL::integer AS report_version\n    FROM cash f JOIN order_header o USING (tenant_id, order_id, region_id)\n    CROSS JOIN p WHERE o.available_at <= p.k\n)\n\n, watermarks AS (\n    SELECT source, last_seen.observed_at, last_seen.complete_through, last_seen.status\n    FROM p CROSS JOIN contract CROSS JOIN jsonb_array_elements_text(spec->''watermarks'') source\n    LEFT JOIN LATERAL (\n        SELECT w.observed_at, w.complete_through, w.status FROM source_watermark w\n        WHERE w.tenant_id=p.tenant_id AND w.source_system=source AND w.observed_at <= p.k\n        ORDER BY w.observed_at DESC LIMIT 1\n    ) last_seen ON true\n), coverage AS (\n    SELECT CASE WHEN count(*) FILTER (WHERE w.observed_at IS NULL)>0 THEN ''COVERAGE_UNKNOWN''\n                WHEN bool_or(w.status=''FAILED'' OR w.complete_through < p.end_at) THEN ''SOURCE_DELAYED''\n           END AS gap,\n           jsonb_build_object(''watermarks'',jsonb_object_agg(source,to_jsonb(w)-''source'')) AS detail\n    FROM watermarks w CROSS JOIN p\n)\n\n, grouped AS (\n    SELECT CASE p.dim WHEN ''day'' THEN (event_at AT TIME ZONE ''Asia/Shanghai'')::date::text\n               WHEN ''channel'' THEN channel_id::text WHEN ''region'' THEN region_id::text\n               WHEN ''site'' THEN site_id::text WHEN ''sku'' THEN sku_id::text WHEN ''spu'' THEN spu_id::text\n               WHEN ''category'' THEN category_id::text ELSE ''total'' END AS group_key,\n           sum(amount)::numeric AS value,\n           array_agg(DISTINCT report_version ORDER BY report_version) FILTER (WHERE report_version IS NOT NULL) AS versions\n    FROM facts CROSS JOIN p\n    WHERE (p.all_regions OR p.region_ids @> jsonb_build_array(region_id))\n      AND (NOT p.filters ? ''channel'' OR channel_id=(p.filters->>''channel'')::bigint)\n      AND (NOT p.filters ? ''region'' OR region_id=(p.filters->>''region'')::bigint)\n      AND (NOT p.filters ? ''site'' OR site_id=(p.filters->>''site'')::bigint)\n      -- Orders applied the three product filters in one correlated EXISTS before counting.\n      AND (sku_id IS NULL OR NOT p.filters ? ''sku'' OR sku_id=(p.filters->>''sku'')::bigint)\n      AND (spu_id IS NULL OR NOT p.filters ? ''spu'' OR spu_id=(p.filters->>''spu'')::bigint)\n      AND (category_id IS NULL OR NOT p.filters ? ''category'' OR category_id=(p.filters->>''category'')::bigint)\n    GROUP BY 1\n), results AS (\n    SELECT g.group_key, CASE WHEN c.gap IS NULL THEN g.value END AS value,\n           coalesce(c.gap,''OK'') AS status, c.detail ||\n           CASE WHEN g.versions IS NULL THEN ''{}''::jsonb ELSE jsonb_build_object(''report_versions'',g.versions) END AS detail\n    FROM grouped g CROSS JOIN coverage c\n    UNION ALL\n    SELECT CASE WHEN p.dim=''total'' THEN ''total'' END,\n           CASE WHEN c.gap IS NULL AND p.dim=''total'' THEN 0::numeric END,\n           coalesce(c.gap, CASE WHEN p.dim=''total'' THEN ''OK'' ELSE ''NO_FACTS'' END), c.detail\n    FROM p CROSS JOIN coverage c WHERE NOT EXISTS (SELECT FROM grouped)\n)\n\nSELECT group_key, value, status, detail, c.d0 AS period_start, c.d1 AS period_end,\n       c.k AS as_of, c.release_id AS data_release, ''Asia/Shanghai''::text AS business_timezone,\n       spec->>''unit'' AS unit\nFROM checked c CROSS JOIN contract CROSS JOIN LATERAL (\n    SELECT r.* FROM results r WHERE c.invalid IS NULL\n    UNION ALL\n    SELECT NULL::text, NULL::numeric, c.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"5006b4006671f16efced9f81472311d946f4332a2c2487e8d40edf2461457e44","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day","channel","region","site"]},"filters":{"type":"object","additionalProperties":false,"properties":{"channel":{"type":"integer","minimum":1,"maximum":9007199254740991},"region":{"type":"integer","minimum":1,"maximum":9007199254740991},"site":{"type":"integer","minimum":1,"maximum":9007199254740991}}}}},"result_schema":{"type":"object","additionalProperties":false,"required":["group_key","value","status","detail","period_start","period_end","as_of","data_release","business_timezone","unit"],"properties":{"group_key":{"type":["string","null"]},"value":{"type":["string","null"],"pattern":"^-?[0-9]+(\\.[0-9]+)?$"},"status":{"enum":["OK","INVALID_WINDOW","UNSUPPORTED_DIMENSION","UNSUPPORTED_FILTER","SCOPE_DENIED","RELEASE_UNAVAILABLE","OUTSIDE_COVERAGE","SOURCE_DELAYED","COVERAGE_UNKNOWN","NO_FACTS"]},"detail":{"type":"object"},"period_start":{"type":"string","format":"date"},"period_end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"data_release":{"type":"string"},"business_timezone":{"const":"Asia/Shanghai"},"unit":{"const":"CNY_fen"}},"if":{"properties":{"status":{"const":"OK"}}},"then":{"properties":{"value":{"type":"string"}}},"else":{"properties":{"value":{"type":"null"}}}},"target_ref":"compass-retail/semantic-content/1/sales.net_gmv","access":{"scope":"regional","source_release":"diagnostic-v3-20261019","protocol":"postgres_readonly","identity":"verified_session_user","namespace_profiles":{"learner":["pg_catalog","retail_course","pg_temp"],"managed":["pg_catalog","core","ops","pg_temp"]},"required_relations":["tenant","payment","refund","order_header","source_watermark"],"trusted_context_schema":{"type":"object","additionalProperties":false,"required":["tenant_id","data_release","all_regions","region_ids"],"properties":{"tenant_id":{"type":"integer"},"data_release":{"const":"diagnostic-v3-20261019"},"all_regions":{"type":"boolean"},"region_ids":{"type":"array","uniqueItems":true,"items":{"type":"integer","minimum":1}}}},"retail_tenant_id":102},"ref":"102/sales.net_gmv","tenant":"99500000-0000-4000-8000-000000000011","workspace":"99500000-0000-4000-8000-000000000022","source":"retail:102"},{"sql":"WITH contract(spec) AS (VALUES (''{\"release\":\"diagnostic-v3-20261019\",\"dimensions\":[\"day\",\"channel\",\"region\",\"site\",\"sku\",\"spu\",\"category\"],\"filters\":[\"channel\",\"region\",\"site\",\"sku\",\"spu\",\"category\"],\"unit\":\"CNY_fen\",\"access\":\"regional\",\"watermarks\":[\"ERP\",\"OMS\"],\"start\":\"2023-01-01\",\"end\":\"2026-04-01\"}''::jsonb))\n-- $1: validated business request. $2: server-attested source scope, never a model argument.\n, input AS (\n    SELECT ($1::jsonb->>''start'')::date AS d0, ($1::jsonb->>''end'')::date AS d1,\n           ($1::jsonb->>''as_of'')::timestamptz AS k, coalesce($1::jsonb->>''group_by'',''total'') AS dim,\n           coalesce($1::jsonb->''filters'',''{}'') AS filters,\n           ($2::jsonb->>''tenant_id'')::smallint AS tenant_id, $2::jsonb->>''data_release'' AS release_id,\n           ($2::jsonb->>''all_regions'')::boolean AS all_regions, $2::jsonb->''region_ids'' AS region_ids\n), checked AS (\n    SELECT i.*, i.d0::timestamp AT TIME ZONE ''Asia/Shanghai'' AS start_at,\n           i.d1::timestamp AT TIME ZONE ''Asia/Shanghai'' AS end_at,\n           CASE WHEN i.d0 IS NULL OR i.d1 IS NULL OR i.k IS NULL OR i.d1 <= i.d0 THEN ''INVALID_WINDOW''\n                WHEN i.dim <> ''total'' AND NOT (spec->''dimensions'' ? i.dim) THEN ''UNSUPPORTED_DIMENSION''\n                WHEN EXISTS (SELECT FROM jsonb_object_keys(i.filters) f WHERE NOT (spec->''filters'' ? f))\n                     THEN ''UNSUPPORTED_FILTER''\n                WHEN i.all_regions IS NULL OR (NOT i.all_regions AND\n                     (coalesce(jsonb_array_length(i.region_ids),0) = 0 OR spec->>''access'' = ''all_regions''\n                      OR (i.filters ? ''region'' AND NOT (i.region_ids @> jsonb_build_array(i.filters->''region'')))))\n                     THEN ''SCOPE_DENIED''\n                WHEN t.release_id IS NULL OR i.release_id IS DISTINCT FROM t.release_id\n                     OR t.release_id <> spec->>''release'' THEN ''RELEASE_UNAVAILABLE''\n                WHEN (CASE WHEN spec ? ''first_snapshot'' THEN i.d1-1 ELSE i.d0 END) < (spec->>''start'')::date OR i.d1 > (spec->>''end'')::date THEN ''OUTSIDE_COVERAGE''\n           END AS invalid\n    FROM input i CROSS JOIN contract LEFT JOIN tenant t ON t.tenant_id = i.tenant_id\n), p AS (SELECT * FROM checked WHERE invalid IS NULL)\n\n, facts AS (\n    SELECT r.recognized_at AS event_at, o.channel_id, o.region_id, o.selling_site_id AS site_id,\n           u.sku_id, s.spu_id, product.category_id, r.amount_cent AS amount, NULL::integer AS report_version\n    FROM revenue_entry r JOIN order_unit u USING (tenant_id,order_unit_id,region_id)\n    JOIN order_header o USING (tenant_id,order_id,region_id)\n    JOIN sku s USING (tenant_id,sku_id) JOIN spu product USING (tenant_id,spu_id)\n    JOIN p ON p.tenant_id=r.tenant_id\n    WHERE r.entry_type IN (''DELIVERY'',''RETURN_ACCEPTED'') AND r.recognized_at >= p.start_at\n      AND r.recognized_at < p.end_at AND greatest(r.available_at,u.available_at,o.available_at) <= p.k\n)\n\n, watermarks AS (\n    SELECT source, last_seen.observed_at, last_seen.complete_through, last_seen.status\n    FROM p CROSS JOIN contract CROSS JOIN jsonb_array_elements_text(spec->''watermarks'') source\n    LEFT JOIN LATERAL (\n        SELECT w.observed_at, w.complete_through, w.status FROM source_watermark w\n        WHERE w.tenant_id=p.tenant_id AND w.source_system=source AND w.observed_at <= p.k\n        ORDER BY w.observed_at DESC LIMIT 1\n    ) last_seen ON true\n), coverage AS (\n    SELECT CASE WHEN count(*) FILTER (WHERE w.observed_at IS NULL)>0 THEN ''COVERAGE_UNKNOWN''\n                WHEN bool_or(w.status=''FAILED'' OR w.complete_through < p.end_at) THEN ''SOURCE_DELAYED''\n           END AS gap,\n           jsonb_build_object(''watermarks'',jsonb_object_agg(source,to_jsonb(w)-''source'')) AS detail\n    FROM watermarks w CROSS JOIN p\n)\n\n, grouped AS (\n    SELECT CASE p.dim WHEN ''day'' THEN (event_at AT TIME ZONE ''Asia/Shanghai'')::date::text\n               WHEN ''channel'' THEN channel_id::text WHEN ''region'' THEN region_id::text\n               WHEN ''site'' THEN site_id::text WHEN ''sku'' THEN sku_id::text WHEN ''spu'' THEN spu_id::text\n               WHEN ''category'' THEN category_id::text ELSE ''total'' END AS group_key,\n           sum(amount)::numeric AS value,\n           array_agg(DISTINCT report_version ORDER BY report_version) FILTER (WHERE report_version IS NOT NULL) AS versions\n    FROM facts CROSS JOIN p\n    WHERE (p.all_regions OR p.region_ids @> jsonb_build_array(region_id))\n      AND (NOT p.filters ? ''channel'' OR channel_id=(p.filters->>''channel'')::bigint)\n      AND (NOT p.filters ? ''region'' OR region_id=(p.filters->>''region'')::bigint)\n      AND (NOT p.filters ? ''site'' OR site_id=(p.filters->>''site'')::bigint)\n      -- Orders applied the three product filters in one correlated EXISTS before counting.\n      AND (sku_id IS NULL OR NOT p.filters ? ''sku'' OR sku_id=(p.filters->>''sku'')::bigint)\n      AND (spu_id IS NULL OR NOT p.filters ? ''spu'' OR spu_id=(p.filters->>''spu'')::bigint)\n      AND (category_id IS NULL OR NOT p.filters ? ''category'' OR category_id=(p.filters->>''category'')::bigint)\n    GROUP BY 1\n), results AS (\n    SELECT g.group_key, CASE WHEN c.gap IS NULL THEN g.value END AS value,\n           coalesce(c.gap,''OK'') AS status, c.detail ||\n           CASE WHEN g.versions IS NULL THEN ''{}''::jsonb ELSE jsonb_build_object(''report_versions'',g.versions) END AS detail\n    FROM grouped g CROSS JOIN coverage c\n    UNION ALL\n    SELECT CASE WHEN p.dim=''total'' THEN ''total'' END,\n           CASE WHEN c.gap IS NULL AND p.dim=''total'' THEN 0::numeric END,\n           coalesce(c.gap, CASE WHEN p.dim=''total'' THEN ''OK'' ELSE ''NO_FACTS'' END), c.detail\n    FROM p CROSS JOIN coverage c WHERE NOT EXISTS (SELECT FROM grouped)\n)\n\nSELECT group_key, value, status, detail, c.d0 AS period_start, c.d1 AS period_end,\n       c.k AS as_of, c.release_id AS data_release, ''Asia/Shanghai''::text AS business_timezone,\n       spec->>''unit'' AS unit\nFROM checked c CROSS JOIN contract CROSS JOIN LATERAL (\n    SELECT r.* FROM results r WHERE c.invalid IS NULL\n    UNION ALL\n    SELECT NULL::text, NULL::numeric, c.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"bbe3b0571a5323a15ba64357d2d27773d50236d743291b1ab08dfff4b9102b15","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day","channel","region","site","sku","spu","category"]},"filters":{"type":"object","additionalProperties":false,"properties":{"channel":{"type":"integer","minimum":1,"maximum":9007199254740991},"region":{"type":"integer","minimum":1,"maximum":9007199254740991},"site":{"type":"integer","minimum":1,"maximum":9007199254740991},"sku":{"type":"integer","minimum":1,"maximum":9007199254740991},"spu":{"type":"integer","minimum":1,"maximum":9007199254740991},"category":{"type":"integer","minimum":1,"maximum":9007199254740991}}}}},"result_schema":{"type":"object","additionalProperties":false,"required":["group_key","value","status","detail","period_start","period_end","as_of","data_release","business_timezone","unit"],"properties":{"group_key":{"type":["string","null"]},"value":{"type":["string","null"],"pattern":"^-?[0-9]+(\\.[0-9]+)?$"},"status":{"enum":["OK","INVALID_WINDOW","UNSUPPORTED_DIMENSION","UNSUPPORTED_FILTER","SCOPE_DENIED","RELEASE_UNAVAILABLE","OUTSIDE_COVERAGE","SOURCE_DELAYED","COVERAGE_UNKNOWN","NO_FACTS"]},"detail":{"type":"object"},"period_start":{"type":"string","format":"date"},"period_end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"data_release":{"type":"string"},"business_timezone":{"const":"Asia/Shanghai"},"unit":{"const":"CNY_fen"}},"if":{"properties":{"status":{"const":"OK"}}},"then":{"properties":{"value":{"type":"string"}}},"else":{"properties":{"value":{"type":"null"}}}},"target_ref":"compass-retail/semantic-content/1/finance.recognized_revenue","access":{"scope":"regional","source_release":"diagnostic-v3-20261019","protocol":"postgres_readonly","identity":"verified_session_user","namespace_profiles":{"learner":["pg_catalog","retail_course","pg_temp"],"managed":["pg_catalog","core","ops","pg_temp"]},"required_relations":["tenant","revenue_entry","order_unit","order_header","sku","spu","source_watermark"],"trusted_context_schema":{"type":"object","additionalProperties":false,"required":["tenant_id","data_release","all_regions","region_ids"],"properties":{"tenant_id":{"type":"integer"},"data_release":{"const":"diagnostic-v3-20261019"},"all_regions":{"type":"boolean"},"region_ids":{"type":"array","uniqueItems":true,"items":{"type":"integer","minimum":1}}}},"retail_tenant_id":101},"ref":"101.finance/finance.recognized_revenue","tenant":"99500000-0000-4000-8000-000000000010","workspace":"99500000-0000-4000-8000-000000000020","source":"retail:101"},{"sql":"WITH contract(spec) AS (VALUES (''{\"release\":\"diagnostic-v3-20261019\",\"dimensions\":[\"day\",\"campaign\",\"channel\"],\"filters\":[\"campaign\",\"channel\"],\"unit\":\"ratio\",\"access\":\"all_regions\",\"watermarks\":[],\"start\":\"2023-01-01\",\"end\":\"2026-01-01\"}''::jsonb))\n-- $1: validated business request. $2: server-attested source scope, never a model argument.\n, input AS (\n    SELECT ($1::jsonb->>''start'')::date AS d0, ($1::jsonb->>''end'')::date AS d1,\n           ($1::jsonb->>''as_of'')::timestamptz AS k, coalesce($1::jsonb->>''group_by'',''total'') AS dim,\n           coalesce($1::jsonb->''filters'',''{}'') AS filters,\n           ($2::jsonb->>''tenant_id'')::smallint AS tenant_id, $2::jsonb->>''data_release'' AS release_id,\n           ($2::jsonb->>''all_regions'')::boolean AS all_regions, $2::jsonb->''region_ids'' AS region_ids\n), checked AS (\n    SELECT i.*, i.d0::timestamp AT TIME ZONE ''Asia/Shanghai'' AS start_at,\n           i.d1::timestamp AT TIME ZONE ''Asia/Shanghai'' AS end_at,\n           CASE WHEN i.d0 IS NULL OR i.d1 IS NULL OR i.k IS NULL OR i.d1 <= i.d0 THEN ''INVALID_WINDOW''\n                WHEN i.dim <> ''total'' AND NOT (spec->''dimensions'' ? i.dim) THEN ''UNSUPPORTED_DIMENSION''\n                WHEN EXISTS (SELECT FROM jsonb_object_keys(i.filters) f WHERE NOT (spec->''filters'' ? f))\n                     THEN ''UNSUPPORTED_FILTER''\n                WHEN i.all_regions IS NULL OR (NOT i.all_regions AND\n                     (coalesce(jsonb_array_length(i.region_ids),0) = 0 OR spec->>''access'' = ''all_regions''\n                      OR (i.filters ? ''region'' AND NOT (i.region_ids @> jsonb_build_array(i.filters->''region'')))))\n                     THEN ''SCOPE_DENIED''\n                WHEN t.release_id IS NULL OR i.release_id IS DISTINCT FROM t.release_id\n                     OR t.release_id <> spec->>''release'' THEN ''RELEASE_UNAVAILABLE''\n                WHEN (CASE WHEN spec ? ''first_snapshot'' THEN i.d1-1 ELSE i.d0 END) < (spec->>''start'')::date OR i.d1 > (spec->>''end'')::date THEN ''OUTSIDE_COVERAGE''\n           END AS invalid\n    FROM input i CROSS JOIN contract LEFT JOIN tenant t ON t.tenant_id = i.tenant_id\n), p AS (SELECT * FROM checked WHERE invalid IS NULL)\n\n, expected AS (\n    SELECT c.campaign_id, c.target_channel_id AS channel_id, p.d0+n AS day\n    FROM p JOIN campaign c ON c.tenant_id=p.tenant_id\n    JOIN channel ch ON (ch.tenant_id,ch.channel_id)=(c.tenant_id,c.target_channel_id)\n    CROSS JOIN generate_series(0,p.d1-p.d0-1) n\n    WHERE ch.channel_type=''PLATFORM'' AND c.available_at <= p.k\n      AND c.starts_at < ((p.d0+n+1)::timestamp AT TIME ZONE ''Asia/Shanghai'')\n      AND c.ends_at > ((p.d0+n)::timestamp AT TIME ZONE ''Asia/Shanghai'')\n      AND (NOT p.filters ? ''channel'' OR c.target_channel_id=(p.filters->>''channel'')::bigint)\n      AND (NOT p.filters ? ''campaign'' OR c.campaign_id=(p.filters->>''campaign'')::bigint)\n), activity AS (\n    SELECT e.*, a.report_version, a.coverage_status, a.attributed_paid_cent-a.attributed_refund_cent AS net,\n           spend.amount, spend.regions, spend.versions\n    FROM expected e CROSS JOIN p\n    LEFT JOIN LATERAL (\n        SELECT r.report_version,r.coverage_status,r.attributed_paid_cent,r.attributed_refund_cent\n        FROM campaign_attribution_daily r\n        WHERE (r.tenant_id,r.campaign_id,r.channel_id,r.cohort_date)=(p.tenant_id,e.campaign_id,e.channel_id,e.day)\n          AND r.attribution_model=''PLATFORM_LAST_CLICK_7D'' AND r.model_version=''1'' AND r.available_at <= p.k\n        ORDER BY r.report_version DESC LIMIT 1\n    ) a ON true\n    CROSS JOIN LATERAL (\n        SELECT sum(latest.spend_cent) AS amount, count(latest.report_version) AS regions,\n               jsonb_object_agg(region,latest.report_version ORDER BY region) AS versions\n        FROM generate_series(1,7) region LEFT JOIN LATERAL (\n            SELECT r.spend_cent,r.report_version FROM campaign_daily r\n            WHERE (r.tenant_id,r.campaign_id,r.channel_id,r.report_date,r.region_id)=\n                  (p.tenant_id,e.campaign_id,e.channel_id,e.day,region) AND r.available_at <= p.k\n            ORDER BY r.report_version DESC LIMIT 1\n        ) latest ON true\n    ) spend\n), cells AS (\n    SELECT a.*, CASE WHEN report_version IS NULL THEN ''ATTRIBUTION_MISSING''\n                     WHEN coverage_status IS DISTINCT FROM ''KNOWN'' OR net IS NULL THEN ''ATTRIBUTION_UNKNOWN''\n                     WHEN regions < 7 THEN ''SPEND_INCOMPLETE'' END AS gap,\n           CASE p.dim WHEN ''day'' THEN day::text WHEN ''campaign'' THEN campaign_id::text\n                      WHEN ''channel'' THEN channel_id::text ELSE ''total'' END AS group_key\n    FROM activity a CROSS JOIN p\n), totals AS (\n    SELECT group_key, sum(net)::numeric AS numerator, sum(amount)::numeric AS denominator,\n           array_agg(DISTINCT gap ORDER BY gap) FILTER (WHERE gap IS NOT NULL) AS gaps,\n           jsonb_agg(jsonb_build_object(''day'',day,''campaign'',campaign_id,''channel'',channel_id,\n               ''attribution_version'',report_version,''spend_versions'',versions,''gap'',gap)\n               ORDER BY day,campaign_id,channel_id) AS source_versions\n    FROM cells GROUP BY group_key\n), results AS (\n    SELECT group_key, CASE WHEN gaps IS NULL THEN numerator/nullif(denominator,0) END AS value,\n           CASE WHEN cardinality(gaps)>1 THEN ''MULTIPLE_GAPS'' WHEN gaps IS NOT NULL THEN gaps[1]\n                WHEN denominator=0 THEN ''ZERO_SPEND'' ELSE ''OK'' END AS status,\n           jsonb_build_object(''activity_days'',source_versions,''gaps'',gaps,\n               ''net_cent'',CASE WHEN gaps IS NULL THEN numerator END,\n               ''spend_cent'',CASE WHEN gaps IS NULL THEN denominator END) AS detail\n    FROM totals\n    UNION ALL\n    SELECT CASE WHEN dim=''total'' THEN ''total'' END,NULL::numeric,CASE WHEN k < end_at THEN ''PERIOD_NOT_CLOSED'' ELSE ''NO_ACTIVITY'' END,''{}''::jsonb\n    FROM p WHERE NOT EXISTS (SELECT FROM cells)\n)\n\nSELECT group_key, value, status, detail, c.d0 AS period_start, c.d1 AS period_end,\n       c.k AS as_of, c.release_id AS data_release, ''Asia/Shanghai''::text AS business_timezone,\n       spec->>''unit'' AS unit\nFROM checked c CROSS JOIN contract CROSS JOIN LATERAL (\n    SELECT r.* FROM results r WHERE c.invalid IS NULL\n    UNION ALL\n    SELECT NULL::text, NULL::numeric, c.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"514bc2fb47e6ded1c495e02fc85f3b7ca4db4ffa969bfbbffcb882cebce3f917","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day","campaign","channel"]},"filters":{"type":"object","additionalProperties":false,"properties":{"campaign":{"type":"integer","minimum":1,"maximum":9007199254740991},"channel":{"type":"integer","minimum":1,"maximum":9007199254740991}}}}},"result_schema":{"type":"object","additionalProperties":false,"required":["group_key","value","status","detail","period_start","period_end","as_of","data_release","business_timezone","unit"],"properties":{"group_key":{"type":["string","null"]},"value":{"type":["string","null"],"pattern":"^-?[0-9]+(\\.[0-9]+)?$"},"status":{"enum":["OK","INVALID_WINDOW","UNSUPPORTED_DIMENSION","UNSUPPORTED_FILTER","SCOPE_DENIED","RELEASE_UNAVAILABLE","OUTSIDE_COVERAGE","ATTRIBUTION_MISSING","ATTRIBUTION_UNKNOWN","SPEND_INCOMPLETE","MULTIPLE_GAPS","ZERO_SPEND","NO_ACTIVITY","PERIOD_NOT_CLOSED"]},"detail":{"type":"object"},"period_start":{"type":"string","format":"date"},"period_end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"data_release":{"type":"string"},"business_timezone":{"const":"Asia/Shanghai"},"unit":{"const":"ratio"}},"if":{"properties":{"status":{"const":"OK"}}},"then":{"properties":{"value":{"type":"string"}}},"else":{"properties":{"value":{"type":"null"}}}},"target_ref":"compass-retail/semantic-content/1/marketing.net_roas","access":{"scope":"all_regions","source_release":"diagnostic-v3-20261019","protocol":"postgres_readonly","identity":"verified_session_user","namespace_profiles":{"learner":["pg_catalog","retail_course","pg_temp"],"managed":["pg_catalog","core","ops","pg_temp"]},"required_relations":["tenant","campaign","channel","campaign_attribution_daily","campaign_daily"],"trusted_context_schema":{"type":"object","additionalProperties":false,"required":["tenant_id","data_release","all_regions","region_ids"],"properties":{"tenant_id":{"type":"integer"},"data_release":{"const":"diagnostic-v3-20261019"},"all_regions":{"type":"boolean"},"region_ids":{"type":"array","uniqueItems":true,"items":{"type":"integer","minimum":1}}}},"retail_tenant_id":101},"ref":"101.marketing/marketing.net_roas","tenant":"99500000-0000-4000-8000-000000000010","workspace":"99500000-0000-4000-8000-000000000020","source":"retail:101"},{"sql":"WITH contract(spec) AS (VALUES (''{\"release\":\"diagnostic-v3-20261019\",\"dimensions\":[\"day\",\"site\",\"region\",\"sku\",\"spu\",\"category\"],\"filters\":[\"site\",\"region\",\"sku\",\"spu\",\"category\"],\"unit\":\"piece\",\"access\":\"regional\",\"watermarks\":[],\"start\":\"2023-01-01\",\"end\":\"2026-04-01\",\"first_snapshot\":\"2025-10-01\"}''::jsonb))\n-- $1: validated business request. $2: server-attested source scope, never a model argument.\n, input AS (\n    SELECT ($1::jsonb->>''start'')::date AS d0, ($1::jsonb->>''end'')::date AS d1,\n           ($1::jsonb->>''as_of'')::timestamptz AS k, coalesce($1::jsonb->>''group_by'',''total'') AS dim,\n           coalesce($1::jsonb->''filters'',''{}'') AS filters,\n           ($2::jsonb->>''tenant_id'')::smallint AS tenant_id, $2::jsonb->>''data_release'' AS release_id,\n           ($2::jsonb->>''all_regions'')::boolean AS all_regions, $2::jsonb->''region_ids'' AS region_ids\n), checked AS (\n    SELECT i.*, i.d0::timestamp AT TIME ZONE ''Asia/Shanghai'' AS start_at,\n           i.d1::timestamp AT TIME ZONE ''Asia/Shanghai'' AS end_at,\n           CASE WHEN i.d0 IS NULL OR i.d1 IS NULL OR i.k IS NULL OR i.d1 <= i.d0 THEN ''INVALID_WINDOW''\n                WHEN i.dim <> ''total'' AND NOT (spec->''dimensions'' ? i.dim) THEN ''UNSUPPORTED_DIMENSION''\n                WHEN EXISTS (SELECT FROM jsonb_object_keys(i.filters) f WHERE NOT (spec->''filters'' ? f))\n                     THEN ''UNSUPPORTED_FILTER''\n                WHEN i.all_regions IS NULL OR (NOT i.all_regions AND\n                     (coalesce(jsonb_array_length(i.region_ids),0) = 0 OR spec->>''access'' = ''all_regions''\n                      OR (i.filters ? ''region'' AND NOT (i.region_ids @> jsonb_build_array(i.filters->''region'')))))\n                     THEN ''SCOPE_DENIED''\n                WHEN t.release_id IS NULL OR i.release_id IS DISTINCT FROM t.release_id\n                     OR t.release_id <> spec->>''release'' THEN ''RELEASE_UNAVAILABLE''\n                WHEN (CASE WHEN spec ? ''first_snapshot'' THEN i.d1-1 ELSE i.d0 END) < (spec->>''start'')::date OR i.d1 > (spec->>''end'')::date THEN ''OUTSIDE_COVERAGE''\n           END AS invalid\n    FROM input i CROSS JOIN contract LEFT JOIN tenant t ON t.tenant_id = i.tenant_id\n), p AS (SELECT * FROM checked WHERE invalid IS NULL)\n\n, closing AS (\n    SELECT p.*, d1-1 AS day, (d1::timestamp - interval ''1 second'') AT TIME ZONE ''Asia/Shanghai'' AS closing_at FROM p\n), expected AS (\n    SELECT DISTINCT a.site_id,a.sku_id,a.region_id,s.spu_id,u.category_id\n    FROM closing c JOIN assortment a ON a.tenant_id=c.tenant_id\n    JOIN sku s ON (s.tenant_id,s.sku_id)=(a.tenant_id,a.sku_id)\n    JOIN spu u ON (u.tenant_id,u.spu_id)=(s.tenant_id,s.spu_id)\n    WHERE a.valid_from <= c.day AND c.day < a.valid_to AND a.available_at <= c.k\n      AND (c.all_regions OR c.region_ids @> jsonb_build_array(a.region_id))\n      AND (NOT c.filters ? ''region'' OR a.region_id=(c.filters->>''region'')::bigint)\n      AND (NOT c.filters ? ''site'' OR a.site_id=(c.filters->>''site'')::bigint)\n      AND (NOT c.filters ? ''sku'' OR a.sku_id=(c.filters->>''sku'')::bigint)\n      AND (NOT c.filters ? ''spu'' OR s.spu_id=(c.filters->>''spu'')::bigint)\n      AND (NOT c.filters ? ''category'' OR u.category_id=(c.filters->>''category'')::bigint)\n), selected AS (\n    SELECT e.*, s.available_qty, s.available_qty=s.sellable_qty-s.reserved_qty AS balanced,\n           CASE c.dim WHEN ''day'' THEN c.day::text WHEN ''site'' THEN e.site_id::text\n                 WHEN ''region'' THEN e.region_id::text WHEN ''sku'' THEN e.sku_id::text\n                 WHEN ''spu'' THEN e.spu_id::text WHEN ''category'' THEN e.category_id::text ELSE ''total'' END AS group_key\n    FROM expected e CROSS JOIN closing c LEFT JOIN inventory_snapshot s\n      ON (s.tenant_id,s.snapshot_date,s.site_id,s.sku_id,s.region_id,s.as_of)=\n         (c.tenant_id,c.day,e.site_id,e.sku_id,e.region_id,c.closing_at) AND s.available_at <= c.k\n), totals AS (\n    SELECT group_key,count(*) AS expected_count,count(available_qty) AS visible_count,\n           bool_and(balanced) AS balanced,sum(available_qty)::numeric AS qty,\n           jsonb_agg(jsonb_build_array(site_id,sku_id) ORDER BY site_id,sku_id)\n               FILTER (WHERE available_qty IS NULL) AS missing\n    FROM selected GROUP BY group_key\n), evaluated AS (\n    SELECT coalesce(t.group_key, CASE WHEN c.dim=''total'' THEN ''total'' END) AS group_key, t.qty,\n           CASE WHEN c.day < (spec->>''first_snapshot'')::date THEN ''OUTSIDE_SNAPSHOT_COVERAGE''\n                WHEN c.k < c.closing_at THEN ''BEFORE_CLOSE''\n                WHEN t.expected_count IS NULL THEN ''NO_ASSORTMENT''\n                WHEN t.visible_count=0 THEN ''SNAPSHOT_NOT_AVAILABLE''\n                WHEN t.visible_count<t.expected_count THEN ''SNAPSHOT_INCOMPLETE''\n                WHEN NOT t.balanced THEN ''QUANTITY_MISMATCH'' ELSE ''OK'' END AS status,\n           jsonb_build_object(''snapshot_date'',c.day,''as_of'',c.closing_at,''expected'',coalesce(t.expected_count,0),\n                              ''visible'',coalesce(t.visible_count,0),''missing_site_sku'',coalesce(t.missing,''[]'')) AS detail\n    FROM closing c CROSS JOIN contract LEFT JOIN totals t ON true\n), results AS (\n    SELECT group_key,CASE WHEN status=''OK'' THEN qty END AS value,status,detail FROM evaluated\n)\n\nSELECT group_key, value, status, detail, c.d0 AS period_start, c.d1 AS period_end,\n       c.k AS as_of, c.release_id AS data_release, ''Asia/Shanghai''::text AS business_timezone,\n       spec->>''unit'' AS unit\nFROM checked c CROSS JOIN contract CROSS JOIN LATERAL (\n    SELECT r.* FROM results r WHERE c.invalid IS NULL\n    UNION ALL\n    SELECT NULL::text, NULL::numeric, c.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"3cda9cc486541b1a529c7a4084ed412434d44e37c18122f03cc43dfaef33bddc","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day","site","region","sku","spu","category"]},"filters":{"type":"object","additionalProperties":false,"propertie