          ($1::jsonb->>''as_of'')::timestamptz AS k, coalesce($1::jsonb->>''group_by'',''total'') AS dim,\n           coalesce($1::jsonb->''filters'',''{}'') AS filters,\n           ($2::jsonb->>''tenant_id'')::smallint AS tenant_id, $2::jsonb->>''data_release'' AS release_id,\n           ($2::jsonb->>''all_regions'')::boolean AS all_regions, $2::jsonb->''region_ids'' AS region_ids\n), checked AS (\n    SELECT i.*, i.d0::timestamp AT TIME ZONE ''Asia/Shanghai'' AS start_at,\n           i.d1::timestamp AT TIME ZONE ''Asia/Shanghai'' AS end_at,\n           CASE WHEN i.d0 IS NULL OR i.d1 IS NULL OR i.k IS NULL OR i.d1 <= i.d0 THEN ''INVALID_WINDOW''\n                WHEN i.dim <> ''total'' AND NOT (spec->''dimensions'' ? i.dim) THEN ''UNSUPPORTED_DIMENSION''\n                WHEN EXISTS (SELECT FROM jsonb_object_keys(i.filters) f WHERE NOT (spec->''filters'' ? f))\n                     THEN ''UNSUPPORTED_FILTER''\n                WHEN i.all_regions IS NULL OR (NOT i.all_regions AND\n                     (coalesce(jsonb_array_length(i.region_ids),0) = 0 OR spec->>''access'' = ''all_regions''\n                      OR (i.filters ? ''region'' AND NOT (i.region_ids @> jsonb_build_array(i.filters->''region'')))))\n                     THEN ''SCOPE_DENIED''\n                WHEN t.release_id IS NULL OR i.release_id IS DISTINCT FROM t.release_id\n                     OR t.release_id <> spec->>''release'' THEN ''RELEASE_UNAVAILABLE''\n                WHEN (CASE WHEN spec ? ''first_snapshot'' THEN i.d1-1 ELSE i.d0 END) < (spec->>''start'')::date OR i.d1 > (spec->>''end'')::date THEN ''OUTSIDE_COVERAGE''\n           END AS invalid\n    FROM input i CROSS JOIN contract LEFT JOIN tenant t ON t.tenant_id = i.tenant_id\n), p AS (SELECT * FROM checked WHERE invalid IS NULL)\n\n, days AS (SELECT d0+n AS day FROM p,generate_series(0,d1-d0-1) n),\nreadiness AS (\n    SELECT day,s.status FROM days CROSS JOIN p LEFT JOIN LATERAL (\n        SELECT a.status FROM asset_period_status a\n        WHERE a.tenant_id=p.tenant_id AND a.asset_id=''core.channel_product_daily''\n          AND a.period_start=day AND a.period_end=day+1 AND a.available_at <= p.k\n        ORDER BY a.observed_at DESC LIMIT 1\n    ) s ON true\n), lines AS (\n    SELECT r.report_date,r.channel_id,r.paid_amount_cent\n    FROM p JOIN channel_product_daily r ON r.tenant_id=p.tenant_id AND r.report_version=1\n    WHERE r.report_date >= p.d0 AND r.report_date < p.d1 AND r.available_at <= p.k\n      AND (p.all_regions OR p.region_ids @> jsonb_build_array(r.region_id))\n      AND (NOT p.filters ? ''channel'' OR r.channel_id=(p.filters->>''channel'')::bigint)\n      AND (NOT p.filters ? ''region'' OR r.region_id=(p.filters->>''region'')::bigint)\n), daily AS (\n    SELECT d.day,d.status,count(l.paid_amount_cent) AS row_count,sum(l.paid_amount_cent) AS cents\n    FROM readiness d LEFT JOIN lines l ON l.report_date=d.day GROUP BY d.day,d.status\n), totals AS (\n    SELECT CASE WHEN p.dim=''day'' THEN d.day::text ELSE ''total'' END AS group_key,\n           sum(d.row_count)::bigint AS row_count,sum(d.cents)::numeric AS cents,\n           array_agg(d.day ORDER BY d.day) FILTER (WHERE d.row_count=0) AS empty_days,\n           array_agg(d.day ORDER BY d.day) FILTER (WHERE d.status IS NULL OR d.status=''PENDING'') AS not_ready,\n           bool_or(d.status IS NULL) AS unknown\n    FROM daily d CROSS JOIN p GROUP BY 1\n), results AS (\n    SELECT group_key,CASE WHEN not_ready IS NULL THEN cents END AS value,\n           CASE WHEN unknown THEN ''COVERAGE_UNKNOWN'' WHEN not_ready IS NOT NULL THEN ''REPORT_INCOMPLETE''\n                WHEN row_count=0 THEN ''NO_REPORT_ROWS'' ELSE ''OK'' END AS status,\n           jsonb_build_object(''row_count'',row_count,''report_versions'',CASE WHEN row_count>0 THEN ''[1]''::jsonb ELSE ''[]''::jsonb END,\n               ''no_visible_row_days'',coalesce(to_jsonb(empty_days),''[]''),''unready_days'',coalesce(to_jsonb(not_ready),''[]'')) AS detail\n    FROM totals\n)\n\nSELECT group_key, value, status, detail, c.d0 AS period_start, c.d1 AS period_end,\n       c.k AS as_of, c.release_id AS data_release, ''Asia/Shanghai''::text AS business_timezone,\n       spec->>''unit'' AS unit\nFROM checked c CROSS JOIN contract CROSS JOIN LATERAL (\n    SELECT r.* FROM results r WHERE c.invalid IS NULL\n    UNION ALL\n    SELECT NULL::text, NULL::numeric, c.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"ca1b3512f5a4f573a883653db944d2efa2e9691147a96336d9f0cf363f51b53e","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day"]},"filters":{"type":"object","additionalProperties":false,"properties":{"channel":{"type":"integer","minimum":1,"maximum":9007199254740991},"region":{"type":"integer","minimum":1,"maximum":9007199254740991}}}}},"result_schema":{"type":"object","additionalProperties":false,"required":["group_key","value","status","detail","period_start","period_end","as_of","data_release","business_timezone","unit"],"properties":{"group_key":{"type":["string","null"]},"value":{"type":["string","null"],"pattern":"^-?[0-9]+(\\.[0-9]+)?$"},"status":{"enum":["OK","INVALID_WINDOW","UNSUPPORTED_DIMENSION","UNSUPPORTED_FILTER","SCOPE_DENIED","RELEASE_UNAVAILABLE","OUTSIDE_COVERAGE","COVERAGE_UNKNOWN","REPORT_INCOMPLETE","NO_REPORT_ROWS"]},"detail":{"type":"object"},"period_start":{"type":"string","format":"date"},"period_end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"data_release":{"type":"string"},"business_timezone":{"const":"Asia/Shanghai"},"unit":{"const":"CNY_fen"}},"if":{"properties":{"status":{"const":"OK"}}},"then":{"properties":{"value":{"type":"string"}}},"else":{"properties":{"value":{"type":"null"}}}},"target_ref":"compa