IS NULL OR i.k IS NULL OR i.d1 <= i.d0 THEN ''INVALID_WINDOW''\n                WHEN i.dim <> ''total'' AND NOT (spec->''dimensions'' ? i.dim) THEN ''UNSUPPORTED_DIMENSION''\n                WHEN EXISTS (SELECT FROM jsonb_object_keys(i.filters) f WHERE NOT (spec->''filters'' ? f))\n                     THEN ''UNSUPPORTED_FILTER''\n                WHEN i.all_regions IS NULL OR (NOT i.all_regions AND\n                     (coalesce(jsonb_array_length(i.region_ids),0) = 0 OR spec->>''access'' = ''all_regions''\n                      OR (i.filters ? ''region'' AND NOT (i.region_ids @> jsonb_build_array(i.filters->''region'')))))\n                     THEN ''SCOPE_DENIED''\n                WHEN t.release_id IS NULL OR i.release_id IS DISTINCT FROM t.release_id\n                     OR t.release_id <> spec->>''release'' THEN ''RELEASE_UNAVAILABLE''\n                WHEN (CASE WHEN spec ? ''first_snapshot'' THEN i.d1-1 ELSE i.d0 END) < (spec->>''start'')::date OR i.d1 > (spec->>''end'')::date THEN ''OUTSIDE_COVERAGE''\n           END AS invalid\n    FROM input i CROSS JOIN contract LEFT JOIN tenant t ON t.tenant_id = i.tenant_id\n), p AS (SELECT * FROM checked WHERE invalid IS NULL)\n\n, days AS (SELECT d0+n AS day FROM p,generate_series(0,d1-d0-1) n),\nreadiness AS (\n    SELECT day,s.status FROM days CROSS JOIN p LEFT JOIN LATERAL (\n        SELECT a.status FROM asset_period_status a\n        WHERE a.tenant_id=p.tenant_id AND a.asset_id=''core.channel_product_daily''\n          AND a.period_start=day AND a.period_end=day+1 AND a.available_at <= p.k\n        ORDER BY a.observed_at DESC LIMIT 1\n    ) s ON true\n), lines AS (\n    SELECT r.report_date,r.channel_id,r.paid_amount_cent\n    FROM p JOIN channel_product_daily r ON r.tenant_id=p.tenant_id AND r.report_version=1\n    WHERE r.report_date >= p.d0 AND r.report_date < p.d1 AND r.available_at <= p.k\n      AND (p.all_regions OR p.region_ids @> jsonb_build_array(r.region_id))\n      AND (NOT p.filters ? ''channel'' OR r.channel_id=(p.filters->>''channel'')::bigint)\n      AND (NOT p.filters ? ''region'' OR r.region_id=(p.filters->>''region'')::bigint)\n), daily AS (\n    SELECT d.day,d.status,count(l.paid_amount_cent) AS row_count,sum(l.paid_amount_cent) AS cents\n    FROM readiness d LEFT JOIN lines l ON l.report_date=d.day GROUP BY d.day,d.status\n), totals AS (\n    SELECT CASE WHEN p.dim=''day'' THEN d.day::text ELSE ''total'' END AS group_key,\n           sum(d.row_count)::bigint AS row_count,sum(d.cents)::numeric AS cents,\n           array_agg(d.day ORDER BY d.day) FILTER (WHERE d.row_count=0) AS empty_days,\n           array_agg(d.day ORDER BY d.day) FILTER (WHERE d.status IS NULL OR d.status=''PENDING'') AS not_ready,\n           bool_or(d.status IS NULL) AS unknown\n    FROM daily d CROSS JOIN p GROUP BY 1\n), results AS (\n    SELECT group_key,CASE WHEN not_ready IS NULL THEN cents END AS value,\n           CASE WHEN unknown THEN ''COVERAGE_UNKNOWN'' WHEN not_ready IS NOT NULL THEN ''REPORT_INCOMPLETE''\n                WHEN row_count=0 THEN ''NO_REPORT_ROWS'' ELSE ''OK'' END AS status,\n           jsonb_build_object(''row_count'',row_count,''report_versions'',CASE WHEN row_count>0 THEN ''[1]''::jsonb ELSE ''[]''::jsonb END,\n               ''no_visible_row_days'',coalesce(to_jsonb(empty_days),''[]''),''unready_days'',coalesce(to_jsonb(not_ready),''[]'')) AS detail\n    FROM totals\n)\n\nSELECT group_key, value, status, detail, c.d0 AS period_start, c.d1 AS period_end,\n       c.k AS as_of, c.release_id AS data_release, ''Asia/Shanghai''::text AS business_timezone,\n       spec->>''unit'' AS unit\nFROM checked c CROSS JOIN contract CROSS JOIN LATERAL (\n    SELECT r.* FROM results r WHERE c.invalid IS NULL\n    UNION ALL\n    SELECT NULL::text, NULL::numeric, c.invalid, ''{}''::jsonb WHERE c.invalid IS NOT NULL\n) receipt ORDER BY group_key NULLS FIRST\n","target_hash":"ca1b3512f5a4f573a883653db944d2efa2e9691147a96336d9f0cf363f51b53e","parameter_schema":{"type":"object","additionalProperties":false,"required":["start","end","as_of"],"properties":{"start":{"type":"string","format":"date"},"end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"group_by":{"enum":["total","day"]},"filters":{"type":"object","additionalProperties":false,"properties":{"channel":{"type":"integer","minimum":1,"maximum":9007199254740991},"region":{"type":"integer","minimum":1,"maximum":9007199254740991}}}}},"result_schema":{"type":"object","additionalProperties":false,"required":["group_key","value","status","detail","period_start","period_end","as_of","data_release","business_timezone","unit"],"properties":{"group_key":{"type":["string","null"]},"value":{"type":["string","null"],"pattern":"^-?[0-9]+(\\.[0-9]+)?$"},"status":{"enum":["OK","INVALID_WINDOW","UNSUPPORTED_DIMENSION","UNSUPPORTED_FILTER","SCOPE_DENIED","RELEASE_UNAVAILABLE","OUTSIDE_COVERAGE","COVERAGE_UNKNOWN","REPORT_INCOMPLETE","NO_REPORT_ROWS"]},"detail":{"type":"object"},"period_start":{"type":"string","format":"date"},"period_end":{"type":"string","format":"date"},"as_of":{"type":"string","format":"date-time"},"data_release":{"type":"string"},"business_timezone":{"const":"Asia/Shanghai"},"unit":{"const":"CNY_fen"}},"if":{"properties":{"status":{"const":"OK"}}},"then":{"properties":{"value":{"type":"string"}}},"else":{"properties":{"value":{"type":"null"}}}},"target_ref":"compass-retail/semantic-content/1/channel.first_report_paid_amount","access":{"scope":"regional","source_release":"diagnostic-v3-20261019","protocol":"postgres_readonly","identity":"verified_session_user","namespace_profiles":{"learner":["pg_catalog","retail_course","pg_temp"],"managed":["pg_catalog","core","ops","pg_temp"]},"required_relations":["tenant","channel_product_daily","asset_period_status"],"trusted_context_schema":{"type":"object","additionalProperties":false,"required":["tenant_id","data_release","all_regions","region_ids"],"properties":{"tenant_id":{"type":"integer"},"data_release":{"const":"diagnostic-v3-20261019"},"all_regions":{"type":"boolean"},"region_ids":{"type":"array","uniqueItems":true,"items":{"type":"integer","minimum":1}}}},"retail_tenant_id":102},"ref":"102/channel.first_report_paid_amount","tenant":"99500000-0000-4000-8000-000000000011","workspace":"99500000-0000-4000-8000-000000000022","source":"retail:102"}],"installer_hash":"1cb5a7ad1f905f7edd6abe7190e780703e56ac8721d97bff044d09488a4fd98a"}','7fd5eebbab8597b24301fd82f0f536df7a166cecc9c3b88d85cfa908699dc0e3');
-- Both entry points supply the same checked pg_temp.seed_input and one transaction.
DO $semantic_import$
DECLARE
    edition jsonb;
    expected_digest text;
    installed_digest text;
BEGIN
    SELECT body->'edition',digest INTO STRICT edition,expected_digest FROM pg_temp.seed_input;
    IF NOT EXISTS (SELECT FROM pg_database WHERE datname=current_database()
                   AND shobj_description(oid,'pg_database')='compass:web/main') THEN
        RAISE EXCEPTION 'Unregistered Web database target';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(edition->>'locator',0));
    SELECT digest INTO installed_digest FROM web.semantic_source
        WHERE locator=edition->>'locator' AND source_version=edition->>'version';
    IF FOUND THEN
        IF installed_digest <> expected_digest AND installed_digest IS DISTINCT FROM
           (SELECT compatible_digest FROM pg_temp.seed_input) THEN
            RAISE EXCEPTION 'Semantic content differs for this edition; use a new reviewed version';
        END IF;
        UPDATE pg_temp.seed_input SET outcome='already_installed';
        RETURN;
    END IF;
    IF NOT EXISTS (SELECT FROM web.app_user WHERE id=(edition->>'editor')::uuid
                   AND login_name='teaching.platform' AND is_platform_admin AND status='active') THEN
        RAISE EXCEPTION 'Install the Web teaching fixture before the retail semantics edition';
    END IF;
    INSERT INTO web.semantic_source(locator,source_version,digest)
    SELECT body->'edition'->>'locator',body->'edition'->>'version',digest FROM pg_temp.seed_input;

    CREATE TEMP TABLE seed_scopes ON COMMIT DROP AS
    SELECT s.key,s.kind,s.tenant,s.department,s."user" AS owner_user
    FROM pg_temp.seed_input CROSS JOIN LATERAL jsonb_to_recordset(body->'scopes')
         AS s(key text,kind text,tenant uuid,department text,"user" uuid);
    ALTER TABLE pg_temp.seed_scopes ADD PRIMARY KEY(key);
    INSERT INTO web.semantic_scopes(kind,tenant_id,department_key,owner_user_id)
    SELECT kind,tenant,department,owner_user FROM pg_temp.seed_scopes
    ON CONFLICT (kind,tenant_id,department_key,owner_user_id) DO NOTHING;
    ALTER TABLE pg_temp.seed_scopes ADD COLUMN id uuid;
    UPDATE pg_temp.seed_scopes s SET id=w.scope_id FROM web.semantic_scopes w
    WHERE (s.kind,s.tenant,s.department,s.owner_user)
          IS NOT DISTINCT FROM (w.kind,w.tenant_id,w.department_key,w.owner_user_id);
    ALTER TABLE pg_temp.seed_scopes ALTER COLUMN id SET NOT NULL;

    CREATE TEMP TABLE seed_assets ON COMMIT DROP AS
    SELECT a->>'ref' AS ref,a,gen_random_uuid() AS asset,gen_random_uuid() AS version,
           (SELECT id FROM pg_temp.seed_scopes WHERE key=a->>'scope') AS scope,
           (body->'edition'->>'editor')::uuid AS editor,
           (SELECT source_id FROM web.semantic_source
            WHERE locator=body->'edition'->>'locator' AND source_version=body->'edition'->>'version') AS source
    FROM pg_temp.seed_input CROSS JOIN LATERAL jsonb_array_elements(body->'assets') a;
    ALTER TABLE pg_temp.seed_assets ADD PRIMARY KEY(ref);

    -- A pre-existing identity outside this import raises a unique violation and rolls back the whole edition.
    INSERT INTO web.semantic_assets(asset_id,owner_scope_id,kind,code,domain,responsible_ref,creator_user_id)
    SELECT asset,scope,a->>'kind',a->>'code',a->>'domain',a->>'responsible',editor FROM pg_temp.seed_assets;

    INSERT INTO web.semantic_versions(version_id,asset_id,version_no,usage_scope_id,editor_user_id,
        name,summary,grain,unit,schema_version,definition,source_id,source_position,digest)
    SELECT version,asset,1,scope,editor,a->>'name',a->>'summary',a->>'grain',a->>'unit',1,a->'definition',
           source,a->>'position',encode(sha256(convert_to(a::text,'UTF8')),'hex')
    FROM pg_temp.seed_assets;

    INSERT INTO web.semantic_aliases(origin_version_id,target_asset_id,scope_id,locale,alias_norm,display_alias)
    SELECT (SELECT version FROM pg_temp.seed_assets WHERE ref=v->>'ref'),
           (SELECT asset FROM pg_temp.seed_assets WHERE ref=v->>'ref'),
           (SELECT id FROM pg_temp.seed_scopes WHERE key=v->>'scope'),'zh-CN',v->>'alias_norm',v->>'display_alias'
    FROM pg_temp.seed_input CROSS JOIN LATERAL jsonb_array_elements(body->'aliases') v;

    INSERT INTO web.semantic_relations(from_version_id,kind,to_asset_id,scope_id,role,rule)
    SELECT (SELECT version FROM pg_temp.seed_assets WHERE ref=r->>'from'),r->>'kind',
           (SELECT asset FROM pg_temp.seed_assets WHERE ref=r->>'to'),
           (SELECT id FROM pg_temp.seed_scopes WHERE key=r->>'scope'),r->>'role',r->'rule'
    FROM pg_temp.seed_input CROSS JOIN LATERAL jsonb_array_elements(body->'relations') r;

    INSERT INTO web.execution_bindings(version_id,tenant_id,workspace_id,source_ref,mode,target_ref,sql_text,
        target_hash,parameter_schema,result_schema,access_requirements)
    SELECT (SELECT version FROM pg_temp.seed_assets WHERE ref=b->>'ref'),(b->>'tenant')::uuid,
           (b->>'workspace')::uuid,b->>'source','trusted_sql',b->>'target_ref',b->>'sql',b->>'target_hash',
           b->'parameter_schema',b->'result_schema',b->'access'
    FROM pg_temp.seed_input CROSS JOIN LATERAL jsonb_array_elements(body->'bindings') b;

    -- Pins affect discovery. Only explicit term -> metric mappings supply a departmental default.
    UPDATE pg_temp.seed_input SET outcome='installed';
END
$semantic_import$;

SELECT outcome,digest FROM pg_temp.seed_input;
COMMIT;
